import json, os
BASE="/home/hatch/workspace/divination/benchmark/phase3/runs/round96/predictions"
os.makedirs(BASE, exist_ok=True)
def T(cm=False,ru=False,di=False,reason=""):
    return {"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":reason}
def W(cid,pred,basis,conf,trig):
    d={"case_id":cid,"prediction_text":pred,"basis":basis,"confidence":conf,"trigger":trig}
    with open(f"{BASE}/{cid}.json","w",encoding="utf-8") as f:
        json.dump(d,f,ensure_ascii=False,indent=2)
    return len(json.dumps(d,ensure_ascii=False).encode())

